SIDE = TASK_CFG["arm"]


def pad_faces(model, data, pf):
    """Per finger: the inner face from the collision mesh's triangles that face the other finger within 25 degrees."""
    a, c = pf["a"], pf["c"]
    vertical = np.array([0.0, 0.0, 1.0])
    cent, tri = {}, {}
    for name in ("left_finger", "right_finger"):
        b = model.body(f"openarm_{SIDE}_{name}").id
        gs = [g for g in range(model.ngeom) if int(model.geom_bodyid[g]) == b and (model.geom_contype[g] or model.geom_conaffinity[g])]
        T = []
        for g in gs:
            mid = int(model.geom_dataid[g])
            V = model.mesh_vert[model.mesh_vertadr[mid]:model.mesh_vertadr[mid] + model.mesh_vertnum[mid]].astype(float)
            F = model.mesh_face[model.mesh_faceadr[mid]:model.mesh_faceadr[mid] + model.mesh_facenum[mid]]
            Vw = V @ data.geom_xmat[g].reshape(3, 3).T + data.geom_xpos[g]
            T.append(Vw[F])
        tri[name] = np.vstack(T)
        cent[name] = float((tri[name].reshape(-1, 3) @ c).mean())
    out = {}
    for name, T in tri.items():
        other = [k for k in tri if k != name][0]
        d = c if cent[name] < cent[other] else -c                      # toward the other finger
        n = np.cross(T[:, 1] - T[:, 0], T[:, 2] - T[:, 0])
        area = 0.5 * np.linalg.norm(n, axis=1)
        nh = n / np.maximum(np.linalg.norm(n, axis=1, keepdims=True), 1e-12)
        # the triangles' winding may point either way: use the sign that faces the other finger
        sign = np.sign(nh @ d)
        sel = np.abs(nh @ d) >= math.cos(math.radians(25.0))
        N = (nh[sel] * (area[sel] * sign[sel])[:, None]).sum(axis=0)
        N = N / np.linalg.norm(N)
        pts = T[sel].reshape(-1, 3)
        # the face nearest the other finger: keep the triangles whose centroid is within 3 mm of the extreme along d
        cen = T[sel].mean(axis=1)
        ext = (cen @ d).max()
        near = (cen @ d) >= ext - 0.003
        pts = T[sel][near].reshape(-1, 3)
        Nn = (nh[sel][near] * (area[sel][near] * sign[sel][near])[:, None]).sum(axis=0)
        Nn = Nn / np.linalg.norm(Nn)
        pa, pw, pc = pts @ a, pts @ vertical, pts @ d
        yaw = math.degrees(math.atan2(float(Nn @ a), float(Nn @ d)))                       # tilt of the face about the vertical: positive = the face turns toward the tips
        pitch = math.degrees(math.asin(float(np.clip(Nn @ vertical, -1, 1))))
        tip = pa >= pa.max() - 0.002
        root = pa <= pa.min() + 0.002
        out[name] = {"normal": Nn.tolist(), "angle_to_closing_axis_deg": math.degrees(math.acos(float(np.clip(Nn @ d, -1, 1)))), "yaw_toward_tips_deg": yaw, "pitch_deg": pitch,
                     "length_mm": 1000 * float(pa.max() - pa.min()), "height_mm": 1000 * float(pw.max() - pw.min()), "n_triangles": int(near.sum()), "c_at_tip_mm": 1000 * float(pc[tip].mean()),
                     "c_at_root_mm": 1000 * float(pc[root].mean()), "tip_a": float(pa.max()), "d": d.tolist()}
    n1, n2 = np.array(out["left_finger"]["normal"]), np.array(out["right_finger"]["normal"])
    out["angle_between_faces_deg"] = math.degrees(math.acos(float(np.clip(n1 @ -n2, -1, 1))))
    gap_tip = (out["right_finger"]["c_at_tip_mm"] - out["left_finger"]["c_at_tip_mm"]) * (1 if np.array(out["left_finger"]["d"]) @ c > 0 else -1)
    gap_root = (out["right_finger"]["c_at_root_mm"] - out["left_finger"]["c_at_root_mm"]) * (1 if np.array(out["left_finger"]["d"]) @ c > 0 else -1)
    out["gap_tip_mm"], out["gap_root_mm"] = abs(gap_tip), abs(gap_root)
    return out


def make_sampler(model, data, rotate_deg):
    bb = model.body("task_beaker").id
    jq = int(model.joint("task_beaker_free").qposadr[0])
    beaker = gpc.descendants(model, "task_beaker")
    bg = {g for g in range(model.ngeom) if int(model.geom_bodyid[g]) in beaker}
    fgs = {}
    for k in ("left_finger", "right_finger"):
        b = model.body(f"openarm_{SIDE}_{k}").id
        fgs[k] = {g for g in range(model.ngeom) if int(model.geom_bodyid[g]) == b and (model.geom_contype[g] or model.geom_conaffinity[g])}
    walls = [g for g in range(model.ngeom) if model.geom(g).name.startswith("task_beaker_wall_")]
    R = {"rotated": False, "prev": None, "result": None}

    def step(obs):
        arm, S = gpc.H["arm"], gpc.H["S"]
        if arm is None:
            return None
        if rotate_deg and not R["rotated"] and data.time < 0.5:
            q = data.qpos[jq + 3:jq + 7].copy()
            h = math.radians(rotate_deg) / 2
            qz = np.array([math.cos(h), 0.0, 0.0, math.sin(h)])
            new = np.zeros(4)
            mujoco.mju_mulQuat(new, qz, q)
            data.qpos[jq + 3:jq + 7] = new
            mujoco.mj_forward(model, data)
            R["rotated"] = True
        steps = S.get("steps") or []
        cur = steps[S["i"]] if S.get("i") is not None and S["i"] < len(steps) else None
        label = f"{S['ctx'].get('primitive')}:{cur['name']}" if cur is not None else "-"
        if label == "pick:UP" and R["prev"] == "pick:CLOSE" and R["result"] is None:
            pf = gpc.pad_frames(model, data)
            cs = gpc.contacts_on_pads(model, data, bg, fgs, pf)
            faces = pad_faces(model, data, pf)
            bpos = data.xpos[bb].copy()
            Rb = data.xmat[bb].reshape(3, 3)
            axis = Rb[:, 2]
            a, c = pf["a"], pf["c"]
            # the segment pattern against the closing axis
            ch = c - (c @ np.array([0, 0, 1.0])) * np.array([0, 0, 1.0])
            ch /= np.linalg.norm(ch)
            ang_c = math.degrees(math.atan2(ch[1], ch[0]))
            n_seg = len(walls)
            step_deg = 360.0 / n_seg
            wall_angles = []
            for g in walls:
                r = data.geom_xpos[g] - bpos
                wall_angles.append(math.degrees(math.atan2(r[1], r[0])))
            def facet_offset(direction_deg):
                best = min(wall_angles, key=lambda w: abs(((w - direction_deg + 180) % 360) - 180))
                return ((best - direction_deg + 180) % 360) - 180
            fo_plus, fo_minus = facet_offset(ang_c), facet_offset(ang_c + 180.0)
            r_out = BEAKER_CFG["outer_diameter"] / 2
            facet_width_mm = 1000 * 2 * r_out * math.tan(math.pi / n_seg)
            # where a perfectly round beaker would touch each pad: the tangent point of the circle on the pad plane (the plane's yaw away from the closing axis shifts it by R sin(yaw))
            pad_c = pf["pad_center_world"]
            axis_off_a = 1000 * float(((bpos - pad_c) - (((bpos - pad_c) @ axis) * axis)) @ a)
            round_pred, meas = {}, {}
            for k in ("left_finger", "right_finger"):
                yaw = faces[k]["yaw_toward_tips_deg"]
                round_pred[k] = {"offset_from_axis_along_approach_mm_toward_tips": 1000 * r_out * math.sin(math.radians(yaw)), "from_tip_mm": None}
                tip_off = 1000 * float(faces[k]["tip_a"] - (pad_c @ a))                          # the tip edge's distance from the pad centre along the approach
                round_pred[k]["from_tip_mm"] = tip_off - round_pred[k]["offset_from_axis_along_approach_mm_toward_tips"] - axis_off_a * 0.0
                cc = gpc.summarize_contacts(cs[k])
                meas[k] = cc
            R["result"] = {"t": float(data.time), "tilt_deg": float(np.degrees(np.arccos(np.clip(axis[2], -1, 1)))), "faces": faces, "n_segments": n_seg, "segment_step_deg": step_deg, "facet_width_mm": facet_width_mm,
                           "closing_axis_horizontal_deg": ang_c, "facet_nearest_closing_axis_offset_deg": {"plus": fo_plus, "minus": fo_minus}, "pad_centre_to_axis_along_approach_mm": axis_off_a,
                           "round_beaker_prediction": round_pred, "measured_contacts": meas, "rotate_deg": rotate_deg}
        R["prev"] = label
        return None
    return {"name": "cause_sampler", "step": step, "state": R}


def main(args):
    cfg = {**BEAKER_CFG, "liquid_mass": 0.10}
    out = Path(args.out)
    out.mkdir(parents=True, exist_ok=True)
    task = make_pipeline_task(PLAN4, module_hook=gpc.make_hook())
    gc.collect()
    sim = load_task(TASK_CFG, cameras=True, beaker_cfg=cfg)
    holder = {}

    def extra(m, d):
        holder["s"] = make_sampler(m, d, args.rotate_deg)
        return {"cause_sampler": holder["s"]}
    s = run_episode(task, sim.model, sim.data, out_dir=out / "episode", extra_sources=extra, stop_after_handoff_s=None)
    res = {"outcome": s["outcome"], "result": holder["s"]["state"]["result"]}
    tmp = out / "result.json.tmp"
    tmp.write_text(json.dumps(res, indent=1, default=str))
    tmp.replace(out / "result.json")
    print("outcome", s["outcome"], "result", "ok" if res["result"] else "NONE", flush=True)


if __name__ == "__main__":
    ap = argparse.ArgumentParser()
    ap.add_argument("--rotate-deg", type=float, default=0.0)
    ap.add_argument("--out", required=True)
    main(ap.parse_args())
